    "summary": "Broker's timeout for shipping calls was reduced to 6 ms, causing widespread timeouts and upstream failures."
  },
  "confidence": "high",
  "causal_chain": [
    {
      "claim": "Broker configuration changed timeout.shipping_ms from 1000 ms to 6 ms.",
      "status": "confirmed",
      "cites": ["ops-E0001", "broker-L00047"]
    },
    {
      "claim": "Broker client timed out calls to shipping on the first attempt (≈6 ms duration).",
      "status": "confirmed",
      "cites": ["broker-S0129c", "broker-S0129f", "broker-S012a0"]
    },
    {
      "claim": "These timed‑out calls were not recorded by shipping (unanswered).",
      "status": "confirmed",
      "cites": ["broker-S012a4", "broker-S013d3", "broker-S013f3"]
    },
    {
      "claim": "Broker began returning upstream_timeout errors (status 504) in its logs.",
      "status": "confirmed",
